insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('opening-principles', 'Opening principles', 'beginner', 'In the opening: control the centre, develop knights and bishops, and castle early.', '{"paragraphs":["In the opening: control the centre, develop knights and bishops, and castle early.","Knights usually belong on f3 and c3 — pointing at the centre, not the edge."],"fen":"rnbqkbnr/pppp1ppp/8/4p3/4P3/8/PPPP1PPP/RNBQKBNR w KQkq e6 0 2","task":"Develop a knight toward the centre.","accept":["g1f3","b1c3"],"requireMate":false}'::jsonb, 'beginner', 5, 6) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('control-the-centre', 'Control the centre', 'strategy', 'The four central squares — d4, e4, d5, e5 — are the high ground. Pieces placed near them reach more of the board.', '{"paragraphs":["The four central squares — d4, e4, d5, e5 — are the high ground. Pieces placed near them reach more of the board.","Claiming the centre with pawns gives your pieces room to breathe."],"fen":"rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1","task":"Place a pawn in the centre with your first move.","accept":["e2e4","d2d4"],"requireMate":false}'::jsonb, 'intermediate', 5, 7) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('develop-your-pieces', 'Develop your pieces', 'strategy', 'A piece still on its starting square is a soldier who hasn’t joined the fight.', '{"paragraphs":["A piece still on its starting square is a soldier who hasn’t joined the fight.","Bring out a new piece with nearly every opening move. Don’t move the same piece twice without a reason."],"fen":"r1bqkbnr/pppp1ppp/2n5/4p3/4P3/5N2/PPPP1PPP/RNBQKB1R w KQkq - 2 3","task":"Develop a new minor piece to an active square.","accept":["f1c4","f1b5","b1c3"],"requireMate":false}'::jsonb, 'intermediate', 5, 8) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('king-safety', 'King safety', 'strategy', 'A king in the centre is a target once the position opens. Castle before you attack.', '{"paragraphs":["A king in the centre is a target once the position opens. Castle before you attack.","Keep the pawns in front of your castled king where they are unless you have a clear reason."],"fen":"r1bqk2r/pppp1ppp/2n2n2/2b1p3/2B1P3/5N2/PPPP1PPP/RNBQK2R w KQkq - 4 4","task":"Get your king to safety.","accept":["e1g1"],"requireMate":false}'::jsonb, 'intermediate', 5, 9) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('pawn-structure', 'Pawn structure', 'strategy', 'Pawns can’t move backwards, so every pawn decision is permanent.', '{"paragraphs":["Pawns can’t move backwards, so every pawn decision is permanent.","When you have a choice of recapture, capturing toward the centre usually keeps a healthier structure."],"fen":"r1bqkb1r/pppp1ppp/8/4p3/4P3/2n5/PPPP1PPP/R1BQKBNR w KQkq - 0 5","task":"Recapture the knight on c3 — toward the centre.","accept":["b2c3"],"requireMate":false}'::jsonb, 'intermediate', 6, 10) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('space', 'Space', 'strategy', 'Advanced pawns claim territory. The side with more space has easier manoeuvres; the cramped side struggles to coordinate.', '{"paragraphs":["Advanced pawns claim territory. The side with more space has easier manoeuvres; the cramped side struggles to coordinate.","Space is only an advantage if you can support your advanced pawns."],"fen":"rnbqkbnr/ppp2ppp/4p3/3p4/3PP3/8/PPP2PPP/RNBQKBNR w KQkq d6 0 3","task":"Gain space by advancing your e-pawn.","accept":["e4e5"],"requireMate":false}'::jsonb, 'intermediate', 5, 11) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('exchanges', 'Exchanges', 'strategy', 'When you are ahead in material, trade pieces. Every exchange makes your extra material count for more.', '{"paragraphs":["When you are ahead in material, trade pieces. Every exchange makes your extra material count for more.","When you are behind, avoid trades and look for complications."],"fen":"3r2k1/5pp1/7p/8/8/8/5PPP/R2R2K1 w - - 0 1","task":"You are a rook up. Offer the trade.","accept":["d1d8"],"requireMate":false}'::jsonb, 'intermediate', 5, 12) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('fork', 'Fork', 'tactics', 'A fork is one piece attacking two targets at once. Knights are the classic forking piece.', '{"paragraphs":["A fork is one piece attacking two targets at once. Knights are the classic forking piece.","The most powerful forks include a check, so the opponent has no time to save the other piece."],"fen":"r3k3/8/8/1N6/8/8/7P/4K3 w - - 0 1","task":"Fork the king and rook.","accept":["b5c7"],"requireMate":false}'::jsonb, 'intermediate', 4, 13) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('pin', 'Pin', 'tactics', 'A pin freezes a piece because moving it would expose something more valuable behind it.', '{"paragraphs":["A pin freezes a piece because moving it would expose something more valuable behind it.","If the piece behind is the king, the pinned piece cannot legally move at all."],"fen":"4k3/3n4/8/8/8/8/8/4KB2 w - - 0 1","task":"Pin the knight to the king.","accept":["f1b5"],"requireMate":false}'::jsonb, 'intermediate', 4, 14) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('skewer', 'Skewer', 'tactics', 'A skewer is a pin in reverse: the valuable piece is in front, and when it moves you take the piece behind.', '{"paragraphs":["A skewer is a pin in reverse: the valuable piece is in front, and when it moves you take the piece behind."],"fen":"8/8/q2k4/8/8/8/6R1/7K w - - 0 1","task":"Skewer the king and queen.","accept":["g2g6"],"requireMate":false}'::jsonb, 'intermediate', 4, 15) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('discovered-attack', 'Discovered attack', 'tactics', 'When one piece moves out of the way, the piece behind it attacks. If the moving piece gives check too, it is a discovered attack with check.', '{"paragraphs":["When one piece moves out of the way, the piece behind it attacks. If the moving piece gives check too, it is a discovered attack with check."],"fen":"8/4k1q1/8/5P2/3N4/8/8/B3K3 w - - 0 1","task":"Move the knight with check to uncover your bishop.","accept":["d4c6"],"requireMate":false}'::jsonb, 'intermediate', 5, 16) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('double-attack', 'Double attack', 'tactics', 'The queen can attack in eight directions. Combine a check with a second threat and something falls.', '{"paragraphs":["The queen can attack in eight directions. Combine a check with a second threat and something falls."],"fen":"r3k3/8/8/8/8/3Q4/8/4K3 w - - 0 1","task":"Check the king and attack the rook in one move.","accept":["d3e4"],"requireMate":false}'::jsonb, 'intermediate', 4, 17) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('checkmate-patterns', 'Checkmate patterns', 'tactics', 'Strong players don’t calculate every mate — they recognise patterns. The back-rank mate is one of the most common in real games.', '{"paragraphs":["Strong players don’t calculate every mate — they recognise patterns. The back-rank mate is one of the most common in real games.","Give your own king an escape square (called luft) to avoid it."],"fen":"6k1/5ppp/8/8/8/8/5PPP/3R2K1 w - - 0 1","task":"Find the back-rank mate.","accept":[],"requireMate":true}'::jsonb, 'intermediate', 5, 18) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('king-and-pawn', 'King and pawn', 'endgame', 'The rule of the square: draw a square from the pawn to the promotion rank. If the enemy king can’t step inside it, the pawn runs through alone.', '{"paragraphs":["The rule of the square: draw a square from the pawn to the promotion rank. If the enemy king can’t step inside it, the pawn runs through alone."],"fen":"8/8/8/8/k7/8/7P/7K w - - 0 1","task":"The king is outside the square. Push the pawn as far as you can.","accept":["h2h4"],"requireMate":false}'::jsonb, 'intermediate', 5, 19) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('opposition', 'Opposition', 'endgame', 'When kings face each other with one square between them, the player who does not have to move has the opposition.', '{"paragraphs":["When kings face each other with one square between them, the player who does not have to move has the opposition.","Taking the opposition forces the enemy king to give way."],"fen":"8/8/4k3/8/8/4K3/4P3/8 w - - 0 1","task":"Take the opposition by stepping your king forward.","accept":["e3e4"],"requireMate":false}'::jsonb, 'intermediate', 6, 20) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;
insert into public.lessons (slug, title, category, description, content, difficulty, duration_minutes, order_index) values ('basic-rook-endings', 'Basic rook endings', 'endgame', 'A rook is at its best cutting off the enemy king. A king kept away from your pawn cannot stop it.', '{"paragraphs":["A rook is at its best cutting off the enemy king. A king kept away from your pawn cannot stop it."],"fen":"8/8/8/8/2k5/8/4P3/R3K3 w - - 0 1","task":"Cut the black king off along the d-file.","accept":["a1d1"],"requireMate":false}'::jsonb, 'intermediate', 6, 21) on conflict (slug) do update set title = excluded.title, category = excluded.category, description = excluded.description, content = excluded.content, difficulty = excluded.difficulty, duration_minutes = excluded.duration_minutes, order_index = excluded.order_index;

-- Stories (structured). Retired slugs are removed so old content never resurfaces.
delete from public.stories where locale = 'en' and slug not in ('the-golden-stool', 'adwa-1896', 'mansa-musa-and-the-gold', 'timbuktu-manuscripts', 'great-zimbabwe', 'isandlwana', 'njinga-at-luanda', 'ibn-khaldun-asabiyya', 'the-ishango-bone', 'wangari-maathai-trees', 'maurice-ashley', 'go-back-and-get-it', 'the-wisdom-knot', 'senterej', 'oware-counting-ahead', 'africas-chess-pioneers', 'the-oldest-trap');
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('the-golden-stool', 'en', 'The Golden Stool', 'A governor asks to sit on a nation’s most sacred object. What does a people do when its soul is put up for negotiation?', 'By 1900 the Asantehene, Prempeh I, had been sent into exile by the British, and Asante was under heavy colonial pressure.

For the Asante, the Golden Stool was not a throne in the ordinary sense. It was held to carry the spirit of the nation: the living, the dead and those not yet born. It was never meant to be sat on, not even by the king.

In March 1900 the British governor, Sir Frederick Hodgson, addressed Asante leaders in Kumasi. As his speech was recorded, he demanded the Stool for the Queen and asked why it had not been brought for him to sit on.

The chiefs had to answer a demand that touched the deepest symbol of their nation, while their king was in exile and the colonial army was close.

Yaa Asantewaa, Queen Mother of Ejisu, is remembered for rallying resistance: if the men would not fight, she said, the women would. Asante forces besieged the British fort in Kumasi from April until a relief column broke through in mid-July 1900.

Militarily, Asante lost. Yaa Asantewaa and other leaders were exiled to the Seychelles, where she died in 1921, and Asante was absorbed into the Gold Coast colony.

But the Stool was hidden in the forest and never captured. When the British later gave assurances of non-interference, it returned to public life, and it is still at the heart of Asante kingship today.

You can lose a battle and still protect what matters most. Know which things are negotiable and which are not, before the pressure arrives.', 'history', 'stool', 4, 'T. C. McCaskie, State and Society in Pre-Colonial Asante (1995); A. Adu Boahen, Yaa Asantewaa and the Asante–British War of 1900–1 (2003).', 'west', 'GH', 'Asante, present-day Ghana', '1900', 'decision', '{"sections":[{"title":"The situation","body":["By 1900 the Asantehene, Prempeh I, had been sent into exile by the British, and Asante was under heavy colonial pressure.","For the Asante, the Golden Stool was not a throne in the ordinary sense. It was held to carry the spirit of the nation: the living, the dead and those not yet born. It was never meant to be sat on, not even by the king."]},{"title":"The pressure","body":["In March 1900 the British governor, Sir Frederick Hodgson, addressed Asante leaders in Kumasi. As his speech was recorded, he demanded the Stool for the Queen and asked why it had not been brought for him to sit on.","The chiefs had to answer a demand that touched the deepest symbol of their nation, while their king was in exile and the colonial army was close."]}],"think":{"question":"If you were one of the Asante leaders that day, what would you do?","options":[{"key":"a","text":"Hand over the Stool to protect lives and buy time","reflection":"A realistic choice under pressure. But some things, once given, cannot be taken back, and the Stool stood for the nation itself."},{"key":"b","text":"Refuse, hide the Stool, and prepare to resist","reflection":"This is close to what happened. Protecting the symbol mattered more than winning the battle."},{"key":"c","text":"Negotiate quietly and offer something else","reflection":"Diplomacy is often wise. Here, the demand itself was the insult, which made a quiet compromise very hard."}]},"outcome":{"title":"What happened","body":["Yaa Asantewaa, Queen Mother of Ejisu, is remembered for rallying resistance: if the men would not fight, she said, the women would. Asante forces besieged the British fort in Kumasi from April until a relief column broke through in mid-July 1900.","Militarily, Asante lost. Yaa Asantewaa and other leaders were exiled to the Seychelles, where she died in 1921, and Asante was absorbed into the Gold Coast colony.","But the Stool was hidden in the forest and never captured. When the British later gave assurances of non-interference, it returned to public life, and it is still at the heart of Asante kingship today."]},"sankofa":"You can lose a battle and still protect what matters most. Know which things are negotiable and which are not, before the pressure arrives.","known":["Hodgson’s March 1900 visit and demand, the siege of the Kumasi fort and its July relief, and the exile of leaders to the Seychelles are documented.","The Golden Stool was never captured by the British."],"debated":["The exact words of Hodgson’s speech come to us through translation and later retelling.","The Stool’s origin, called down from the sky by the priest Okomfo Anokye for King Osei Tutu, is Asante tradition, not documented history.","Figures for the size of the Asante force vary widely between sources."]}'::jsonb, now() - interval '17 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('adwa-1896', 'en', 'Adwa: the battle won before it was fought', 'One treaty, two languages, two meanings. How Ethiopia turned a sentence into a war, and won.', 'In 1889 Emperor Menelik II signed the Treaty of Wuchale with Italy. Article 17 existed in two versions.

In Amharic, Ethiopia could use Italy’s help in foreign affairs if it wished. In Italian, Ethiopia had to conduct its foreign affairs through Italy, which effectively made it a protectorate.

Italy treated the Italian text as binding. Menelik rejected it. By 1895 the dispute had become a war.

Italy had a modern European army. Menelik had to decide how to face it: fight early, wait, or seek terms.

Menelik and Empress Taytu Betul brought together forces from across the empire. Estimates range from about 73,000 to over 100,000, against roughly 15,000–18,000 Italian and colonial troops. Many Ethiopian soldiers carried modern rifles imported from France and Russia.

On 1 March 1896, the Italian brigades advanced at night through mountain passes with poor maps. Columns lost contact with each other. One brigade followed its guides instead of its map and was cut off. Ethiopian commanders, including Ras Makonnen and Ras Alula, struck the gaps.

Italy suffered one of the heaviest colonial defeats of the era, and its government fell within days. Italy then signed the Treaty of Addis Ababa recognising Ethiopia’s independence.

Read the fine print, in every language that matters. And in strategy, as in chess, the side whose pieces work together usually beats the side with better individual pieces.', 'strategy', 'shield', 5, 'Raymond Jonas, The Battle of Adwa (2011); Harold G. Marcus, The Life and Times of Menelik II (1975).', 'east', 'ET', 'Tigray, Ethiopia', '1889–1896', 'decision', '{"sections":[{"title":"The situation","body":["In 1889 Emperor Menelik II signed the Treaty of Wuchale with Italy. Article 17 existed in two versions.","In Amharic, Ethiopia could use Italy’s help in foreign affairs if it wished. In Italian, Ethiopia had to conduct its foreign affairs through Italy, which effectively made it a protectorate."]},{"title":"The pressure","body":["Italy treated the Italian text as binding. Menelik rejected it. By 1895 the dispute had become a war.","Italy had a modern European army. Menelik had to decide how to face it: fight early, wait, or seek terms."]}],"think":{"question":"What would you prioritise before the decisive battle?","options":[{"key":"a","text":"Attack quickly before the enemy is fully ready","reflection":"Speed can win, but an army that is not supplied and united can break in a long campaign."},{"key":"b","text":"Build alliances, arms and supplies, and let the enemy come to difficult ground","reflection":"This is close to Menelik’s approach: unity among regional rulers, modern rifles bought abroad, and patience."},{"key":"c","text":"Accept the treaty’s Italian version to avoid war","reflection":"It might have bought peace for a while, at the cost of sovereignty, which was the very thing at stake."}]},"outcome":{"title":"What happened","body":["Menelik and Empress Taytu Betul brought together forces from across the empire. Estimates range from about 73,000 to over 100,000, against roughly 15,000–18,000 Italian and colonial troops. Many Ethiopian soldiers carried modern rifles imported from France and Russia.","On 1 March 1896, the Italian brigades advanced at night through mountain passes with poor maps. Columns lost contact with each other. One brigade followed its guides instead of its map and was cut off. Ethiopian commanders, including Ras Makonnen and Ras Alula, struck the gaps.","Italy suffered one of the heaviest colonial defeats of the era, and its government fell within days. Italy then signed the Treaty of Addis Ababa recognising Ethiopia’s independence."]},"sankofa":"Read the fine print, in every language that matters. And in strategy, as in chess, the side whose pieces work together usually beats the side with better individual pieces.","known":["The two versions of Article 17, the date of the battle, and Italy’s recognition of Ethiopian independence afterwards are documented.","Ethiopia was one of very few African states to stay independent through the Scramble for Africa."],"debated":["Troop and casualty figures differ considerably between historians.","Whether the mistranslation was deliberate is still argued."]}'::jsonb, now() - interval '16 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('mansa-musa-and-the-gold', 'en', 'Mansa Musa and the price of gold', 'A king travels to Mecca and gives away so much gold that Cairo talks about it for years. Generosity, strategy, or both?', 'Mansa Musa ruled the Mali Empire for about 25 years in the early 14th century. Mali controlled major sources of West African gold, which flowed north across the Sahara.

In 1324 he set out on the hajj to Mecca, travelling through Cairo with a large caravan.

A ruler on a long journey through foreign lands decides how to present himself. He can travel quietly, or he can make sure the world sees what his kingdom is.

He stayed about three months in Cairo. The Egyptian writer al-Umari, writing years later, reported that the value of gold in Egypt fell after Musa’s visit and stayed lower for at least twelve years.

On the way home his party ran short and borrowed from Cairo merchants. Mali’s fame spread: the Catalan Atlas of 1375 shows a West African ruler holding a gold nugget, described as the richest in the region.

Building work in Timbuktu and Gao during his reign helped make Timbuktu a centre of learning.

Reputation travels further than armies. But be careful with legends: the most famous ‘fact’ about Mansa Musa, that he was the richest person in history, cannot actually be measured.', 'history', 'coin', 4, 'Nehemia Levtzion, Ancient Ghana and Mali (1973); N. Levtzion & J. Hopkins (eds.), Corpus of Early Arabic Sources for West African History (1981).', 'west', 'ML', 'Mali Empire → Cairo', '1324', 'decision', '{"sections":[{"title":"The situation","body":["Mansa Musa ruled the Mali Empire for about 25 years in the early 14th century. Mali controlled major sources of West African gold, which flowed north across the Sahara.","In 1324 he set out on the hajj to Mecca, travelling through Cairo with a large caravan."]},{"title":"The choice","body":["A ruler on a long journey through foreign lands decides how to present himself. He can travel quietly, or he can make sure the world sees what his kingdom is."]}],"think":{"question":"Why might a ruler give away gold so publicly on a journey abroad?","options":[{"key":"a","text":"Personal piety and generosity","reflection":"Religious giving was part of the hajj and is how many accounts frame it."},{"key":"b","text":"To build his kingdom’s reputation with traders, scholars and rulers","reflection":"Reputation is a strategic asset. The Mali he advertised attracted scholars and trade afterwards."},{"key":"c","text":"Both, and it is hard to separate them","reflection":"Probably the most honest answer. Historians often cannot see inside a ruler’s motives."}]},"outcome":{"title":"What happened","body":["He stayed about three months in Cairo. The Egyptian writer al-Umari, writing years later, reported that the value of gold in Egypt fell after Musa’s visit and stayed lower for at least twelve years.","On the way home his party ran short and borrowed from Cairo merchants. Mali’s fame spread: the Catalan Atlas of 1375 shows a West African ruler holding a gold nugget, described as the richest in the region.","Building work in Timbuktu and Gao during his reign helped make Timbuktu a centre of learning."]},"sankofa":"Reputation travels further than armies. But be careful with legends: the most famous ‘fact’ about Mansa Musa, that he was the richest person in history, cannot actually be measured.","known":["His hajj in 1324–25 and his stay in Cairo are recorded in Arabic sources.","Al-Umari reports a fall in the value of gold in Egypt after the visit."],"debated":["Claims of tens of thousands of attendants and tons of gold come from later writers and are treated by historians as exaggeration.","Some historians argue the gold-price change was within normal fluctuation.","‘Richest person ever’ is a modern internet claim; his wealth cannot be converted into modern money in any meaningful way."]}'::jsonb, now() - interval '15 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('timbuktu-manuscripts', 'en', 'Saving the manuscripts of Timbuktu', 'Armed groups take a city of libraries. A librarian has to decide what knowledge is worth risking your life for.', 'For centuries, families in Timbuktu kept manuscripts in their homes: works on law, medicine, astronomy, philosophy, letters and Qurans, from the late 13th to the 20th century. Most are in Arabic; some are in African languages written in Arabic script.

In 2012, armed Islamist groups took control of northern Mali, including Timbuktu.

The libraries were at risk of being looted or destroyed. Moving fragile manuscripts openly would draw attention. Doing nothing could mean losing them forever.

Abdel Kader Haidara, from a long line of Timbuktu manuscript keepers, worked with local families, couriers and international supporters to hide manuscripts and move them to Bamako. Roughly 350,000 manuscripts were evacuated.

Losses still happened: thousands were burned or stolen, including at the Ahmed Baba Institute. Today many of the rescued manuscripts are being digitised, and preserving them in Bamako’s humidity is its own challenge.

Knowledge survives because people decide to carry it. Spreading risk, trusting a network and moving quietly is strategy too.', 'thinkers', 'book', 4, 'Charlie English, The Book Smugglers of Timbuktu (2017); Shamil Jeppie & Souleymane Bachir Diagne (eds.), The Meanings of Timbuktu (2008).', 'west', 'ML', 'Timbuktu & Bamako, Mali', '2012–2013', 'decision', '{"sections":[{"title":"The situation","body":["For centuries, families in Timbuktu kept manuscripts in their homes: works on law, medicine, astronomy, philosophy, letters and Qurans, from the late 13th to the 20th century. Most are in Arabic; some are in African languages written in Arabic script.","In 2012, armed Islamist groups took control of northern Mali, including Timbuktu."]},{"title":"The pressure","body":["The libraries were at risk of being looted or destroyed. Moving fragile manuscripts openly would draw attention. Doing nothing could mean losing them forever."]}],"think":{"question":"If you were responsible for these libraries, what would you do?","options":[{"key":"a","text":"Lock them in the libraries and hope they are ignored","reflection":"It avoids immediate risk, but leaves everything in one place, exactly where an attacker would look."},{"key":"b","text":"Quietly spread them across many family homes, then smuggle them south in small loads","reflection":"Close to what happened. Spreading risk and trusting a network of ordinary people."},{"key":"c","text":"Appeal publicly to the world for protection","reflection":"Attention can help, but it can also make the manuscripts a bigger target."}]},"outcome":{"title":"What happened","body":["Abdel Kader Haidara, from a long line of Timbuktu manuscript keepers, worked with local families, couriers and international supporters to hide manuscripts and move them to Bamako. Roughly 350,000 manuscripts were evacuated.","Losses still happened: thousands were burned or stolen, including at the Ahmed Baba Institute. Today many of the rescued manuscripts are being digitised, and preserving them in Bamako’s humidity is its own challenge."]},"sankofa":"Knowledge survives because people decide to carry it. Spreading risk, trusting a network and moving quietly is strategy too.","known":["The occupation of Timbuktu in 2012–13, the evacuation to Bamako and the destruction of thousands of manuscripts are documented."],"debated":["Exact numbers of manuscripts saved and lost vary between organisations; most of the collection is still uncatalogued."]}'::jsonb, now() - interval '14 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('great-zimbabwe', 'en', 'Great Zimbabwe and the lie about who built it', 'Stone walls 11 metres high, built without mortar. For decades a government insisted Africans could not have built them.', 'Great Zimbabwe was built and occupied roughly between the 11th and 15th centuries by ancestors of the Shona. Its Great Enclosure has dry-stone walls, with no mortar, rising about 11 metres.

Finds at the site include Chinese ceramics, Persian and Syrian objects, glass beads and evidence of gold working, signs of a trade network reaching the Indian Ocean coast and beyond.

Archaeologists concluded in 1905 and again in 1929 that the city was built by Africans. African origin was the scientific consensus by the 1950s.

Yet Rhodesia’s white-minority government pushed the claim that others must have built it, and archaeologists who said otherwise faced censorship.

When the country became independent in 1980, it took its name from the site: Zimbabwe. Its carved soapstone birds appear on the national flag, and the site became a UNESCO World Heritage Site in 1986.

Whoever controls the story of the past shapes the present. When someone says ‘your people could not have done that’, ask what they gain from you believing it.', 'innovation', 'wall', 4, 'Peter Garlake, Great Zimbabwe (1973); Innocent Pikirayi, The Zimbabwe Culture (2001); UNESCO World Heritage listing 364.', 'southern', 'ZW', 'Masvingo, Zimbabwe', '11th–15th century (built) · 20th century (denied)', 'idea', '{"sections":[{"title":"The city","body":["Great Zimbabwe was built and occupied roughly between the 11th and 15th centuries by ancestors of the Shona. Its Great Enclosure has dry-stone walls, with no mortar, rising about 11 metres.","Finds at the site include Chinese ceramics, Persian and Syrian objects, glass beads and evidence of gold working, signs of a trade network reaching the Indian Ocean coast and beyond."]},{"title":"The denial","body":["Archaeologists concluded in 1905 and again in 1929 that the city was built by Africans. African origin was the scientific consensus by the 1950s.","Yet Rhodesia’s white-minority government pushed the claim that others must have built it, and archaeologists who said otherwise faced censorship."]}],"think":{"question":"Why would a government deny who built a monument?","options":[{"key":"a","text":"Honest scientific uncertainty","reflection":"Not really: the evidence had been clear for decades."},{"key":"b","text":"Because history can justify who holds power in the present","reflection":"If Africans had built a great state, colonial claims about African ‘backwardness’ fell apart."},{"key":"c","text":"Because the site is hard to date","reflection":"Dating can be tricky, but it did not change who the builders were."}]},"outcome":{"title":"What happened","body":["When the country became independent in 1980, it took its name from the site: Zimbabwe. Its carved soapstone birds appear on the national flag, and the site became a UNESCO World Heritage Site in 1986."]},"sankofa":"Whoever controls the story of the past shapes the present. When someone says ‘your people could not have done that’, ask what they gain from you believing it.","known":["Construction dates, dry-stone technique, trade finds and the colonial-era censorship are well documented.","The name Zimbabwe comes from the Shona name for the site."],"debated":["Population estimates range from under 10,000 to around 18,000.","Why the city declined is debated: trade shifts, resource strain and political splits have all been proposed."]}'::jsonb, now() - interval '13 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('isandlwana', 'en', 'Isandlwana: the army that wasn’t seen', 'A British general splits his army to chase an enemy he thinks he has found. The real enemy is somewhere else.', 'In January 1879 Britain invaded the Zulu Kingdom of King Cetshwayo. Lord Chelmsford led a column of about 1,800 soldiers and auxiliaries and camped below the hill of Isandlwana.

The Zulu army, around 20,000 strong under commanders including Ntshingwayo kaMahole, moved slowly and stayed hidden.

On 22 January, believing he had located the Zulu army, Chelmsford took a large part of his force out of camp to attack it. The camp was left under Lieutenant-Colonel Pulleine, and it was not fortified.

The main Zulu force attacked the camp using the ‘horns and chest of the buffalo’: a central body that held the enemy while two wings swept round to encircle. More than 1,300 men on the British side were killed. It was one of the worst defeats of a modern army by an African force.

The victory was costly: Zulu losses are estimated in the thousands. Britain returned with a much larger army, defeated the Zulu at Ulundi in July 1879, captured Cetshwayo, and split the kingdom into thirteen chiefdoms.

Never split your forces against an enemy you cannot see. And remember: winning one battle is not the same as winning the war. The best strategists plan for what the other side does next.', 'strategy', 'horns', 5, 'Ian Knight, Zulu Rising (2010); John Laband, Kingdom in Crisis: The Zulu Response to the British Invasion of 1879 (1992).', 'southern', 'ZA', 'Zulu Kingdom, present-day South Africa', 'January 1879', 'decision', '{"sections":[{"title":"The situation","body":["In January 1879 Britain invaded the Zulu Kingdom of King Cetshwayo. Lord Chelmsford led a column of about 1,800 soldiers and auxiliaries and camped below the hill of Isandlwana.","The Zulu army, around 20,000 strong under commanders including Ntshingwayo kaMahole, moved slowly and stayed hidden."]},{"title":"The decision","body":["On 22 January, believing he had located the Zulu army, Chelmsford took a large part of his force out of camp to attack it. The camp was left under Lieutenant-Colonel Pulleine, and it was not fortified."]}],"think":{"question":"What was the biggest mistake on the British side?","options":[{"key":"a","text":"Splitting the force without knowing where the enemy really was","reflection":"Dividing your army is only safe when you know where the threat is."},{"key":"b","text":"Not fortifying the camp","reflection":"A serious error too: the camp had no defensive perimeter."},{"key":"c","text":"Underestimating the enemy","reflection":"Arguably the root of the other two mistakes."}]},"outcome":{"title":"What happened","body":["The main Zulu force attacked the camp using the ‘horns and chest of the buffalo’: a central body that held the enemy while two wings swept round to encircle. More than 1,300 men on the British side were killed. It was one of the worst defeats of a modern army by an African force.","The victory was costly: Zulu losses are estimated in the thousands. Britain returned with a much larger army, defeated the Zulu at Ulundi in July 1879, captured Cetshwayo, and split the kingdom into thirteen chiefdoms."]},"sankofa":"Never split your forces against an enemy you cannot see. And remember: winning one battle is not the same as winning the war. The best strategists plan for what the other side does next.","known":["The date, the split of Chelmsford’s column, the unfortified camp, the encirclement and the scale of losses are documented.","The later defeat at Ulundi (4 July 1879) and the partition of Zululand are documented."],"debated":["Zulu force size and casualty figures vary between historians; most give 20,000–25,000 men and 1,000–3,000 killed."]}'::jsonb, now() - interval '12 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('njinga-at-luanda', 'en', 'Njinga at the negotiating table', 'An envoy walks into a room where only the other side has chairs. Her answer became one of the most famous stories in African diplomacy.', 'In the early 1620s the Portuguese colony at Luanda was waging war on the kingdom of Ndongo. King Ngola Mbandi sent his sister, Njinga, to negotiate. She was royal, experienced and spoke Portuguese.

According to the well-known account of the meeting, the Portuguese governor sat in a chair while only a mat was laid out for her. Where you sit at a negotiation signals who is in charge.

In the story, one of her attendants knelt and Njinga sat on her back, meeting the governor at eye level. She negotiated a treaty and was baptised in Luanda as Ana de Sousa.

She went on to rule Ndongo and conquer Matamba, allied with the Dutch when they took Luanda in 1641, and made peace with Portugal on her own terms in 1656. She ruled until her death in 1663 and is honoured in Angola today.

She was also a ruler of her time: her states took part in the slave trade, and historians caution against making her a simple hero or villain.

Position is part of every negotiation. Sometimes the most important move is refusing the frame you were given, without walking out of the room.', 'strategy', 'seat', 4, 'Linda M. Heywood, Njinga of Angola: Africa’s Warrior Queen (2017); John Thornton, ‘Legitimacy and Political Power: Queen Njinga, 1624–1663’, Journal of African History (1991).', 'central', 'AO', 'Luanda, present-day Angola', '1622', 'decision', '{"sections":[{"title":"The situation","body":["In the early 1620s the Portuguese colony at Luanda was waging war on the kingdom of Ndongo. King Ngola Mbandi sent his sister, Njinga, to negotiate. She was royal, experienced and spoke Portuguese."]},{"title":"The moment","body":["According to the well-known account of the meeting, the Portuguese governor sat in a chair while only a mat was laid out for her. Where you sit at a negotiation signals who is in charge."]}],"think":{"question":"What would you do when the room is set up to make you look smaller?","options":[{"key":"a","text":"Sit on the mat and focus on the substance","reflection":"Sometimes wise. But in diplomacy, accepting a lower position can set the tone for everything that follows."},{"key":"b","text":"Refuse to negotiate until treated as an equal","reflection":"Principled, but it risks ending the talks before they start."},{"key":"c","text":"Change the room without leaving it","reflection":"That is what the story says she did."}]},"outcome":{"title":"What happened","body":["In the story, one of her attendants knelt and Njinga sat on her back, meeting the governor at eye level. She negotiated a treaty and was baptised in Luanda as Ana de Sousa.","She went on to rule Ndongo and conquer Matamba, allied with the Dutch when they took Luanda in 1641, and made peace with Portugal on her own terms in 1656. She ruled until her death in 1663 and is honoured in Angola today.","She was also a ruler of her time: her states took part in the slave trade, and historians caution against making her a simple hero or villain."]},"sankofa":"Position is part of every negotiation. Sometimes the most important move is refusing the frame you were given, without walking out of the room.","known":["The 1621–22 mission to Luanda, her baptism, her rule over Ndongo and Matamba, the Dutch alliance and the 1656 peace are documented."],"debated":["The chair story is a famous account, retold for centuries; details vary and it cannot be verified independently.","Much of what we know comes from Portuguese and Capuchin writers with their own agendas."]}'::jsonb, now() - interval '11 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('ibn-khaldun-asabiyya', 'en', 'Ibn Khaldun and why empires fall', 'A North African scholar noticed a pattern in history: the strength that builds a dynasty is the same thing that comfort slowly destroys.', 'Ibn Khaldun was born in Tunis in 1332. He served rulers across North Africa and Andalusia as a secretary, diplomat and minister, and later became a judge and teacher in Cairo.

In his Muqaddimah, written in the 1370s, he tried to explain why states rise and fall, not through luck, but through patterns.

His key word was asabiyya: group solidarity. A tight, disciplined group with strong asabiyya can take power. Once in power, its members grow comfortable, rely on luxury and paid help, and the solidarity weakens, until a more cohesive group replaces them.

Modern scholars count him among the forerunners of sociology, economics and historiography. In 1400, during the siege of Damascus, he was lowered over the city walls to meet the conqueror Timur.

Success is not the end of the struggle; it is the start of a new test. Stay hungry, stay together, and watch for comfort becoming weakness.', 'thinkers', 'scroll', 4, 'Ibn Khaldun, The Muqaddimah, trans. Franz Rosenthal (1958); Robert Irwin, Ibn Khaldun: An Intellectual Biography (2018).', 'north', 'TN', 'Tunis → Cairo', '1332–1406', 'idea', '{"sections":[{"title":"The thinker","body":["Ibn Khaldun was born in Tunis in 1332. He served rulers across North Africa and Andalusia as a secretary, diplomat and minister, and later became a judge and teacher in Cairo.","In his Muqaddimah, written in the 1370s, he tried to explain why states rise and fall, not through luck, but through patterns."]},{"title":"The idea","body":["His key word was asabiyya: group solidarity. A tight, disciplined group with strong asabiyya can take power. Once in power, its members grow comfortable, rely on luxury and paid help, and the solidarity weakens, until a more cohesive group replaces them."]}],"think":{"question":"Where do you see asabiyya today?","options":[{"key":"a","text":"In a team that wins because everyone works for each other","reflection":"Exactly: a group can beat more talented individuals through cohesion."},{"key":"b","text":"In a company that was hungry as a start-up but slow once successful","reflection":"Ibn Khaldun would recognise this immediately."},{"key":"c","text":"Nowhere: success just depends on resources","reflection":"Resources matter. His point is that resources without cohesion are not enough."}]},"outcome":{"title":"His legacy","body":["Modern scholars count him among the forerunners of sociology, economics and historiography. In 1400, during the siege of Damascus, he was lowered over the city walls to meet the conqueror Timur."]},"sankofa":"Success is not the end of the struggle; it is the start of a new test. Stay hungry, stay together, and watch for comfort becoming weakness.","known":["His life, career and the Muqaddimah are well documented, including in his own autobiography."],"debated":["How far his cycle applies outside the societies he studied is debated; some of his views on other peoples are rightly criticised today."]}'::jsonb, now() - interval '10 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('the-ishango-bone', 'en', 'The Ishango bone: what counts as evidence?', 'Notches on a 20,000-year-old bone. Some see a calculator; others see a tally. This story is about how to tell the difference.', 'In 1950 the Belgian geologist Jean de Heinzelin found a small, dark bone near Ishango, by the Semliki River in what is now the DR Congo. It has 168 notches arranged in three columns, and a piece of quartz fixed to one end.

Its age is debated; the current estimate is about 20,000 years. It is kept today at the Royal Belgian Institute of Natural Sciences in Brussels.

One column shows groups of 11, 13, 17 and 19 notches: the prime numbers between 10 and 20. Others have read the bone as a lunar calendar, a counting tool in base 12, or a simple tally.

Most researchers agree the marks were made on purpose and that the bone is one of the oldest known records of counting. Claims about prime numbers or advanced arithmetic are not accepted as proven.

Pride in African history is strongest when it is accurate. Ask ‘how do we know?’, because the true story is impressive enough.', 'innovation', 'bone', 3, 'Royal Belgian Institute of Natural Sciences; Dirk Huylebrouck, Africa and Mathematics (2019); Olivier Keller, ‘The fables of Ishango’ (2010).', 'central', 'CD', 'Ishango, DR Congo → Brussels', 'c. 20,000 years ago', 'idea', '{"sections":[{"title":"The object","body":["In 1950 the Belgian geologist Jean de Heinzelin found a small, dark bone near Ishango, by the Semliki River in what is now the DR Congo. It has 168 notches arranged in three columns, and a piece of quartz fixed to one end.","Its age is debated; the current estimate is about 20,000 years. It is kept today at the Royal Belgian Institute of Natural Sciences in Brussels."]},{"title":"The readings","body":["One column shows groups of 11, 13, 17 and 19 notches: the prime numbers between 10 and 20. Others have read the bone as a lunar calendar, a counting tool in base 12, or a simple tally."]}],"think":{"question":"One column shows four prime numbers. Does that prove the makers understood primes?","options":[{"key":"a","text":"Yes, that cannot be a coincidence","reflection":"Tempting, but four numbers is a small sample, and many patterns can appear by chance."},{"key":"b","text":"No, it could be a coincidence, and we need more evidence","reflection":"This is the careful answer most researchers give."},{"key":"c","text":"It shows people were counting and recording, which is already remarkable","reflection":"A strong position: the bone is evidence of early record-keeping, without overclaiming."}]},"outcome":{"title":"Where scholars stand","body":["Most researchers agree the marks were made on purpose and that the bone is one of the oldest known records of counting. Claims about prime numbers or advanced arithmetic are not accepted as proven."]},"sankofa":"Pride in African history is strongest when it is accurate. Ask ‘how do we know?’, because the true story is impressive enough.","known":["Discovery in 1950, the notch counts, and its location in Brussels are documented."],"debated":["Its exact age, and whether the marks show arithmetic, a calendar or a tally, are open questions."]}'::jsonb, now() - interval '9 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('wangari-maathai-trees', 'en', 'Wangari Maathai: seven trees', 'Facing soil loss, failing water and an untouchable government, she chose the smallest possible first move.', 'In the 1970s, rural Kenyan women told Wangari Maathai about streams drying up, firewood getting scarce and food harder to grow. Maathai was a scientist: in 1971 she became the first woman in East and Central Africa to earn a PhD.

The problems were huge: deforestation, poverty, land grabs and a government that did not want to be challenged. Where do you start?

The Green Belt Movement began on 5 June 1977 with seven trees in Nairobi. It grew into a movement of thousands of community groups planting trees across Kenya.

Tree planting turned into wider struggles: she led campaigns to protect Uhuru Park and Karura Forest from development, and was beaten and arrested. She later became a member of parliament. In 2004 she became the first African woman to win the Nobel Peace Prize.

Big change can start with a move small enough to do today. Every strong position in chess is built one quiet move at a time.', 'thinkers', 'tree', 4, 'Wangari Maathai, Unbowed: A Memoir (2006); Norwegian Nobel Committee, Nobel Peace Prize 2004.', 'east', 'KE', 'Nairobi, Kenya', '1977–2004', 'decision', '{"sections":[{"title":"The situation","body":["In the 1970s, rural Kenyan women told Wangari Maathai about streams drying up, firewood getting scarce and food harder to grow. Maathai was a scientist: in 1971 she became the first woman in East and Central Africa to earn a PhD."]},{"title":"The choice","body":["The problems were huge: deforestation, poverty, land grabs and a government that did not want to be challenged. Where do you start?"]}],"think":{"question":"Facing a problem that big, what is the best first move?","options":[{"key":"a","text":"Lobby the government for a national policy","reflection":"Important, but slow, and easy to ignore without public pressure."},{"key":"b","text":"Start something small that ordinary people can do themselves","reflection":"That is what she did: planting trees, paying women a small amount for each surviving seedling."},{"key":"c","text":"Write a major report and wait for funding","reflection":"Knowledge matters, but action builds the movement that makes reports matter."}]},"outcome":{"title":"What happened","body":["The Green Belt Movement began on 5 June 1977 with seven trees in Nairobi. It grew into a movement of thousands of community groups planting trees across Kenya.","Tree planting turned into wider struggles: she led campaigns to protect Uhuru Park and Karura Forest from development, and was beaten and arrested. She later became a member of parliament. In 2004 she became the first African woman to win the Nobel Peace Prize."]},"sankofa":"Big change can start with a move small enough to do today. Every strong position in chess is built one quiet move at a time.","known":["Her PhD (1971), the founding of the Green Belt Movement (1977), the Uhuru Park and Karura Forest campaigns, and the 2004 Nobel Peace Prize are documented."],"debated":["Total tree counts vary by source and are best read as estimates."]}'::jsonb, now() - interval '8 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('maurice-ashley', 'en', 'Maurice Ashley: the long road to grandmaster', 'A boy from Jamaica learns chess in Brooklyn parks. Decades later he is a grandmaster and the voice of world chess broadcasts.', 'Maurice Ashley was born in Jamaica in 1966 and moved to the United States at 12, growing up in Brooklyn. He came to chess late by elite standards, as a teenager, playing in parks and clubs.

While still chasing his own titles, he coached school teams from Harlem, the Raging Rooks and the Dark Knights, to national championships.

In 1999 he earned his final grandmaster norm, becoming widely recognised as the first Black chess grandmaster.

He became one of chess’s best-known commentators, covering events from Kasparov vs Deep Blue to the Grand Chess Tour, and was inducted into the US Chess Hall of Fame in 2016.

Your starting point is not your ceiling. Teach what you learn, and build a community that rises with you.', 'chess', 'knight', 3, 'US Chess Hall of Fame; Maurice Ashley, Chess for Success (2005); Move by Move (2024).', 'diaspora', 'JM', 'Jamaica → Brooklyn', '1966–today', 'idea', '{"sections":[{"title":"The road","body":["Maurice Ashley was born in Jamaica in 1966 and moved to the United States at 12, growing up in Brooklyn. He came to chess late by elite standards, as a teenager, playing in parks and clubs.","While still chasing his own titles, he coached school teams from Harlem, the Raging Rooks and the Dark Knights, to national championships."]},{"title":"The breakthrough","body":["In 1999 he earned his final grandmaster norm, becoming widely recognised as the first Black chess grandmaster."]}],"think":{"question":"He started chess late and coached others while still improving himself. What does that teach?","options":[{"key":"a","text":"Teaching others is one of the best ways to learn","reflection":"Explaining an idea exposes the parts you don’t yet understand."},{"key":"b","text":"Starting late is not a reason to stop","reflection":"It changes the route, not the destination."},{"key":"c","text":"Community makes individuals stronger","reflection":"The teams he built became part of his own story."}]},"outcome":{"title":"Today","body":["He became one of chess’s best-known commentators, covering events from Kasparov vs Deep Blue to the Grand Chess Tour, and was inducted into the US Chess Hall of Fame in 2016."]},"sankofa":"Your starting point is not your ceiling. Teach what you learn, and build a community that rises with you.","known":["His birth in Jamaica, the GM norm in 1999, his coaching of Harlem teams and his Hall of Fame induction are documented."],"debated":["Sources differ on whether his title is dated 1999 (final norm) or 2000 (official award)."]}'::jsonb, now() - interval '7 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('go-back-and-get-it', 'en', 'Go back and get it', 'The Akan word behind this platform, and why it fits a game built on memory.', 'Sankofa comes from the Akan of Ghana. It is usually explained as san (return), ko (go) and fa (fetch): go back and get it.

It is tied to a proverb: “Se wo were fi na wosankofa a yenkyi”, it is not wrong to go back for that which you have forgotten.

One Adinkra form shows a bird whose feet face forward while its head turns back to an egg on its back. The egg is the knowledge of the past; the feet say you keep moving.

Every game review in Sankofa Chess is a small act of sankofa: you return to the moment that mattered, take what it teaches, and move on stronger.

Looking back is not going backwards. It is how you collect what you need for the next move.', 'culture', 'sankofa', 3, 'W. Bruce Willis, The Adinkra Dictionary (1998).', 'west', 'GH', 'Akan tradition, Ghana', 'Proverb', 'idea', '{"sections":[{"title":"The word","body":["Sankofa comes from the Akan of Ghana. It is usually explained as san (return), ko (go) and fa (fetch): go back and get it.","It is tied to a proverb: “Se wo were fi na wosankofa a yenkyi”, it is not wrong to go back for that which you have forgotten."]},{"title":"The symbol","body":["One Adinkra form shows a bird whose feet face forward while its head turns back to an egg on its back. The egg is the knowledge of the past; the feet say you keep moving."]}],"think":{"question":"What does ‘going back’ look like for a chess player?","options":[{"key":"a","text":"Reviewing the games you lost","reflection":"Exactly. Most improvement hides in the games we would rather forget."},{"key":"b","text":"Studying old classic games","reflection":"Yes: strong players learn patterns from the past."},{"key":"c","text":"Never repeating the same mistake","reflection":"That is the goal. Going back is how you get there."}]},"outcome":{"title":"Why it matters here","body":["Every game review in Sankofa Chess is a small act of sankofa: you return to the moment that mattered, take what it teaches, and move on stronger."]},"sankofa":"Looking back is not going backwards. It is how you collect what you need for the next move.","known":["Sankofa is an Akan concept and an Adinkra symbol."],"debated":["The breakdown of the word into san-ko-fa is a common explanation; linguists may describe it differently."]}'::jsonb, now() - interval '6 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('the-wisdom-knot', 'en', 'The wisdom knot', 'Adinkra symbols carry whole ideas in a single shape. One of them describes a strong chess player.', 'Adinkra symbols come from the Asante region of Ghana, where they were traditionally stamped onto cloth. Each stands for a proverb, a value or an idea.

Nyansapo, the wisdom knot, is associated with the idea that a wise person chooses the best means to reach a goal.

Dwennimmen, the ram’s horns, stands for strength combined with humility.

Strong players often choose the simple move that keeps control over the flashy one that gives chances away.

Wisdom is choosing the right tool, not the most impressive one.', 'culture', 'nyansapo', 3, 'W. Bruce Willis, The Adinkra Dictionary (1998).', 'west', 'GH', 'Asante, Ghana', 'Adinkra tradition', 'idea', '{"sections":[{"title":"Adinkra","body":["Adinkra symbols come from the Asante region of Ghana, where they were traditionally stamped onto cloth. Each stands for a proverb, a value or an idea."]},{"title":"Nyansapo","body":["Nyansapo, the wisdom knot, is associated with the idea that a wise person chooses the best means to reach a goal.","Dwennimmen, the ram’s horns, stands for strength combined with humility."]}],"think":{"question":"Which is closer to good chess: the most brilliant move, or the right one?","options":[{"key":"a","text":"The most brilliant move","reflection":"Brilliance is beautiful, but it often isn’t needed, and it can be risky."},{"key":"b","text":"The right move for this position","reflection":"That is nyansapo: the best means for the goal in front of you."}]},"outcome":{"title":"At the board","body":["Strong players often choose the simple move that keeps control over the flashy one that gives chances away."]},"sankofa":"Wisdom is choosing the right tool, not the most impressive one.","known":["Nyansapo and Dwennimmen are recorded Adinkra symbols."],"debated":["Meanings of Adinkra symbols can vary between communities and over time."]}'::jsonb, now() - interval '5 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('senterej', 'en', 'Senterej: chess at the Ethiopian court', 'Ethiopia had its own version of chess, with an opening that rewarded fast development.', 'Senterej is a traditional Ethiopian form of chess descended from the older shatranj family. It was played for centuries, including at the royal court.

A notable feature: at the start, players could develop freely at their own pace until the first capture, after which moves alternated normally.

Senterej faded during the twentieth century as international rules spread, but it remains part of Africa’s chess story.

Prepare before you strike. The player who is ready when the fighting starts usually wins it.', 'chess', 'board', 3, 'H. J. R. Murray, A History of Chess (1913); Richard Pankhurst, writings on Ethiopian games.', 'east', 'ET', 'Ethiopia', 'Centuries before the 20th', 'idea', '{"sections":[{"title":"The game","body":["Senterej is a traditional Ethiopian form of chess descended from the older shatranj family. It was played for centuries, including at the royal court.","A notable feature: at the start, players could develop freely at their own pace until the first capture, after which moves alternated normally."]}],"think":{"question":"If both sides could make several moves before the first capture, what would you do first?","options":[{"key":"a","text":"Bring out pieces fast and safely","reflection":"Development first: exactly what modern coaches teach."},{"key":"b","text":"Rush to attack","reflection":"In senterej, an early capture ends the free phase and could leave you less developed than your opponent."}]},"outcome":{"title":"What happened to it","body":["Senterej faded during the twentieth century as international rules spread, but it remains part of Africa’s chess story."]},"sankofa":"Prepare before you strike. The player who is ready when the fighting starts usually wins it.","known":["Senterej is recorded as an Ethiopian chess variant played at court."],"debated":["Details of its rules varied by place and period."]}'::jsonb, now() - interval '4 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('oware-counting-ahead', 'en', 'Oware and the art of counting ahead', 'A West African board game that trains the same muscle as chess calculation.', 'Oware is a mancala game played across Ghana and West Africa; related games are played across the continent and the Caribbean. Players sow seeds around a board of pits and capture by landing on the right count.

Strong players count several sowings ahead and set up captures their opponent doesn’t see coming: calculation without pieces.

Strategic thinking has deep roots across the continent. Chess is one vehicle among many.

Count before you commit. The move you can calculate is the move you can trust.', 'culture', 'oware', 3, 'Alexander J. de Voogt, Mancala Board Games (1997).', 'west', 'GH', 'West Africa', 'Living tradition', 'idea', '{"sections":[{"title":"The game","body":["Oware is a mancala game played across Ghana and West Africa; related games are played across the continent and the Caribbean. Players sow seeds around a board of pits and capture by landing on the right count."]},{"title":"The skill","body":["Strong players count several sowings ahead and set up captures their opponent doesn’t see coming: calculation without pieces."]}],"think":{"question":"What skill do oware and chess share most?","options":[{"key":"a","text":"Calculating several moves ahead","reflection":"Yes: both reward seeing the consequence before you act."},{"key":"b","text":"Memorising openings","reflection":"Helpful in chess, but not the core of either game."}]},"outcome":{"title":"Why it matters","body":["Strategic thinking has deep roots across the continent. Chess is one vehicle among many."]},"sankofa":"Count before you commit. The move you can calculate is the move you can trust.","known":["Oware is a widely played mancala game in West Africa."],"debated":["Rules and names vary by region."]}'::jsonb, now() - interval '3 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('africas-chess-pioneers', 'en', 'Africa’s chess pioneers', 'The players who put African chess on the world map, and the routes they took.', 'Zambia’s Amon Simutowe became the first grandmaster from sub-Saharan Africa. South Africa’s Kenny Solomon became the country’s first grandmaster after winning the African Championship in December 2014.

Egypt’s Bassem Amin has been one of Africa’s strongest players for years. Uganda’s Phiona Mutesi learned in Katwe, Kampala, and represented her country at Chess Olympiads; her story became the 2016 film Queen of Katwe.

Each of them started somewhere ordinary. The next one could be starting today.

Talent needs a door and a habit. Find your club, show up daily, and hold the door for the next player.', 'chess', 'crown', 3, 'FIDE ratings and title records; Tim Crothers, The Queen of Katwe (2012).', 'pan-african', null, 'Zambia · South Africa · Egypt · Uganda', '2000s–today', 'idea', '{"sections":[{"title":"The players","body":["Zambia’s Amon Simutowe became the first grandmaster from sub-Saharan Africa. South Africa’s Kenny Solomon became the country’s first grandmaster after winning the African Championship in December 2014.","Egypt’s Bassem Amin has been one of Africa’s strongest players for years. Uganda’s Phiona Mutesi learned in Katwe, Kampala, and represented her country at Chess Olympiads; her story became the 2016 film Queen of Katwe."]}],"think":{"question":"What do these very different routes have in common?","options":[{"key":"a","text":"Talent","reflection":"Necessary, but not enough on its own."},{"key":"b","text":"Someone who opened the door: a coach, a club, a programme","reflection":"In almost every case, a community made the path possible."},{"key":"c","text":"Years of consistent work","reflection":"Always. Titles are the visible end of a long, quiet process."}]},"outcome":{"title":"Next","body":["Each of them started somewhere ordinary. The next one could be starting today."]},"sankofa":"Talent needs a door and a habit. Find your club, show up daily, and hold the door for the next player.","known":["Titles and events named here are recorded by FIDE and national federations."],"debated":["‘Strongest’ rankings change over time; check current FIDE ratings."]}'::jsonb, now() - interval '2 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;
insert into public.stories (slug, locale, title, excerpt, content, category, symbol, read_minutes, source, region, country, place, era, kind, structure, published_at) values ('the-oldest-trap', 'en', 'The oldest trap on the board', 'A rook and knight pattern that has been winning games for over a thousand years.', 'The Arabian mate, a rook and knight trapping a king in the corner, is one of the oldest checkmate patterns on record, found in early Arabic writings on shatranj, the ancestor of modern chess.

Chess travelled through the Islamic world and across North Africa into Spain and Europe. The game Europe inherited had already passed through many African and Arab hands.

You can solve this exact pattern in the puzzle set: ‘The oldest trap’.

Old wisdom still wins games. Patterns are knowledge someone else paid for; learn them for free.', 'chess', 'arabian', 3, 'H. J. R. Murray, A History of Chess (1913).', 'north', null, 'Shatranj, Arabic world', 'Over a thousand years', 'idea', '{"sections":[{"title":"The pattern","body":["The Arabian mate, a rook and knight trapping a king in the corner, is one of the oldest checkmate patterns on record, found in early Arabic writings on shatranj, the ancestor of modern chess.","Chess travelled through the Islamic world and across North Africa into Spain and Europe. The game Europe inherited had already passed through many African and Arab hands."]}],"think":{"question":"Why do old patterns still win games today?","options":[{"key":"a","text":"Because the geometry of the board hasn’t changed","reflection":"Exactly: a good pattern is a truth about the board, not a fashion."},{"key":"b","text":"Because opponents forget them","reflection":"Partly, which is why studying them gives you an edge."}]},"outcome":{"title":"Try it","body":["You can solve this exact pattern in the puzzle set: ‘The oldest trap’."]},"sankofa":"Old wisdom still wins games. Patterns are knowledge someone else paid for; learn them for free.","known":["The Arabian mate appears in early Arabic shatranj manuscripts."],"debated":["Exact dating of the earliest examples is uncertain."]}'::jsonb, now() - interval '1 days') on conflict (slug, locale) do update set title = excluded.title, excerpt = excluded.excerpt, content = excluded.content, category = excluded.category, symbol = excluded.symbol, read_minutes = excluded.read_minutes, source = excluded.source, region = excluded.region, country = excluded.country, place = excluded.place, era = excluded.era, kind = excluded.kind, structure = excluded.structure;

-- Strategic thoughts
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('stronger-army-weaker-ground', 'en', 'You have the stronger army, but your opponent holds the better terrain. Do you attack now or reposition?', 'Strength on paper means little if the ground fights against you.', '[{"key":"a","text":"Attack now, before they dig in further","style":"bold","perspective":"Sometimes right: time can favour the defender. But attacking uphill wastes your advantage."},{"key":"b","text":"Reposition and make them come to you","style":"patient","perspective":"Often wisest. Make your strength count by choosing where the fight happens."},{"key":"c","text":"Cut their supplies and wait","style":"adaptive","perspective":"Indirect pressure can win without a battle, if you can afford the time."}]'::jsonb, 'In chess: before attacking, improve your worst-placed piece. Fight where your pieces are strongest.', 'develop-your-pieces', 1) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('ally-asks-too-much', 'en', 'An ally offers help you badly need, but asks for something that weakens you later. Do you accept?', 'Short-term rescue, long-term cost.', '[{"key":"a","text":"Accept: survive today, deal with tomorrow later","style":"adaptive","perspective":"Survival matters. But many kingdoms lost their independence one ‘temporary’ concession at a time."},{"key":"b","text":"Negotiate the terms down before accepting","style":"diplomatic","perspective":"Usually the best move: you rarely have to accept the first offer."},{"key":"c","text":"Refuse and find another way","style":"principled","perspective":"Protects your position, if another way really exists."}]'::jsonb, 'In chess: a pawn grab that weakens your king is rarely free. Count the long-term cost.', 'king-safety', 2) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('ahead-what-now', 'en', 'You are clearly winning. Your opponent starts making wild, risky moves. What do you do?', 'The most dangerous moment is often just after you take the lead.', '[{"key":"a","text":"Go for a quick knockout","style":"bold","perspective":"Fine if it is safe. But chaos is exactly what the losing side wants."},{"key":"b","text":"Simplify: trade pieces, remove their chances","style":"patient","perspective":"The classic winning method. Fewer pieces means fewer tricks."},{"key":"c","text":"Check every threat before each move","style":"principled","perspective":"Essential either way. Most won games are lost to one unchecked threat."}]'::jsonb, 'When ahead, trade pieces. When behind, keep pieces and complicate.', 'exchanges', 3) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('two-problems-one-move', 'en', 'You face two problems at once and can only solve one today. How do you choose?', 'Every move is also a decision about what not to do.', '[{"key":"a","text":"Fix the most urgent","style":"adaptive","perspective":"Usually right: an immediate threat outranks a long-term one."},{"key":"b","text":"Fix the one that creates the most options afterwards","style":"patient","perspective":"Strong players think this way: choose the move that keeps the most good moves available."},{"key":"c","text":"Look for one move that helps with both","style":"bold","perspective":"The best answer when it exists, and in chess it often does."}]'::jsonb, 'Look for moves that do two jobs: a developing move that also defends, a check that also attacks.', 'double-attack', 4) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('rival-makes-mistake', 'en', 'Your rival makes a public mistake. You could exploit it now, or quietly let it pass. What do you do?', 'How you win shapes who wants to work with you later.', '[{"key":"a","text":"Take full advantage: that is competition","style":"bold","perspective":"On a chessboard, absolutely. In life, relationships often matter more than one win."},{"key":"b","text":"Take the advantage, but with respect","style":"principled","perspective":"Win cleanly, without humiliation. Most respected leaders do this."},{"key":"c","text":"Let it pass and build trust","style":"diplomatic","perspective":"Sometimes the long game is worth more than the point."}]'::jsonb, 'At the board: punish mistakes, every time. After the game: shake hands and learn together.', null, 5) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('plan-not-working', 'en', 'You have followed a plan for weeks and it isn’t working. Do you stay the course or change it?', 'Stubbornness and persistence look the same from the inside.', '[{"key":"a","text":"Stay the course: plans need time","style":"principled","perspective":"Right if the reasons behind the plan are still true."},{"key":"b","text":"Change it: the situation has changed","style":"adaptive","perspective":"Right if you can name what changed. Changing plans every week is its own mistake."},{"key":"c","text":"Keep the goal, change the method","style":"patient","perspective":"Often the wisest: be firm on direction, flexible on route."}]'::jsonb, 'In chess: if the position changes, your plan must change with it. Ask ‘what does the position need now?’', 'control-the-centre', 6) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('information-or-speed', 'en', 'You can decide now with half the information, or wait a week for the full picture. Which?', 'Waiting has a cost too.', '[{"key":"a","text":"Decide now: speed is an advantage","style":"bold","perspective":"Good when the decision can be corrected later."},{"key":"b","text":"Wait for the full picture","style":"patient","perspective":"Good when the decision is hard to reverse."},{"key":"c","text":"Decide now, but in a way you can adjust","style":"adaptive","perspective":"Often the best of both: a flexible first step."}]'::jsonb, 'In time trouble, pick a safe, flexible move rather than the perfect one.', null, 7) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('team-of-stars', 'en', 'You can build a team of brilliant individuals who don’t get along, or solid players who trust each other. Which wins?', 'Ibn Khaldun called the second thing asabiyya: group solidarity.', '[{"key":"a","text":"The brilliant individuals","style":"bold","perspective":"Talent wins moments. Without coordination, it often loses seasons."},{"key":"b","text":"The team that trusts each other","style":"principled","perspective":"History is full of cohesive groups beating stronger rivals."},{"key":"c","text":"Start with trust, then add talent carefully","style":"patient","perspective":"Most lasting teams are built this way."}]'::jsonb, 'On the board: pieces that protect each other beat pieces that work alone.', 'develop-your-pieces', 8) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('losing-position', 'en', 'You are losing badly. Do you resign with dignity or fight on?', 'Hope and stubbornness again look alike.', '[{"key":"a","text":"Fight on: make them prove it","style":"principled","perspective":"At most levels, opponents miss wins. Many games are saved by refusing to give up."},{"key":"b","text":"Resign and learn from it","style":"adaptive","perspective":"Reasonable when the result is truly certain, especially against strong players."},{"key":"c","text":"Set a practical trap and see if they find the answer","style":"bold","perspective":"A fighting mindset: give them a problem to solve."}]'::jsonb, 'Before resigning, ask: what is the hardest problem I can still give my opponent?', null, 9) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('copy-or-create', 'en', 'A competitor is successful. Do you copy what they do or build something different?', 'The question behind every new venture, including this one.', '[{"key":"a","text":"Copy the parts that work","style":"adaptive","perspective":"Learning from others is smart, but a copy is always one step behind."},{"key":"b","text":"Build something different","style":"bold","perspective":"Harder, riskier, and the only way to lead rather than follow."},{"key":"c","text":"Learn their principles, apply them your own way","style":"patient","perspective":"Sankofa: take what is valuable, make it yours."}]'::jsonb, 'Study master games for their ideas, not to memorise their moves.', null, 10) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('invitation-to-attack', 'en', 'Your opponent leaves something valuable undefended. It looks too easy. Do you take it?', 'Free things are sometimes the most expensive.', '[{"key":"a","text":"Take it: a gift is a gift","style":"bold","perspective":"Often correct. But check first: what does their next move do?"},{"key":"b","text":"Ask why it is undefended before deciding","style":"patient","perspective":"The habit of strong players. Most traps rely on you not asking."},{"key":"c","text":"Ignore it and stick to your plan","style":"principled","perspective":"Sometimes wise, but turning down real material is also a mistake."}]'::jsonb, 'Before any capture: list your opponent’s checks, captures and threats after it.', 'legal-moves-and-captures', 11) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('small-daily-or-big-once', 'en', 'Which builds more skill: one long session a week, or ten minutes every day?', 'The river is filled by many small streams.', '[{"key":"a","text":"One long, deep session","style":"bold","perspective":"Depth matters for hard topics, but memory fades between sessions."},{"key":"b","text":"Ten minutes every day","style":"patient","perspective":"Learning research tends to favour spacing and repetition for retention."},{"key":"c","text":"Daily practice, plus an occasional deep dive","style":"adaptive","perspective":"Probably the strongest combination."}]'::jsonb, 'That is why Sankofa is a daily ritual, not a binge.', null, 12) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('leader-in-crisis', 'en', 'In a crisis, a leader can speak first to calm people, or wait until they have the full facts. What matters more?', 'Silence can look like weakness; speed can spread errors.', '[{"key":"a","text":"Speak early, be honest about what is unknown","style":"diplomatic","perspective":"Usually best: people trust leaders who say what they don’t know."},{"key":"b","text":"Wait until certain","style":"patient","perspective":"Avoids mistakes, but others will fill the silence."},{"key":"c","text":"Act first, explain later","style":"bold","perspective":"Effective in emergencies, risky for trust."}]'::jsonb, 'At the board: when surprised, don’t react instantly. Take a breath, check the threats, then act.', null, 13) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;
insert into public.thoughts (slug, locale, prompt, context, options, takeaway, lesson_slug, sort_order) values ('sacrifice', 'en', 'Would you give up something valuable today for a stronger position tomorrow?', 'Every chess sacrifice asks this question.', '[{"key":"a","text":"Yes, if I can see what I gain","style":"bold","perspective":"A calculated sacrifice is an investment."},{"key":"b","text":"Only if I’m sure","style":"patient","perspective":"Careful, but certainty is rare, and opportunities pass."},{"key":"c","text":"No: hold what you have","style":"principled","perspective":"Solid, but positions that never take risks often drift into passivity."}]'::jsonb, 'A sacrifice is only good if you can name what you get: time, an open king, a decisive attack.', 'fork', 14) on conflict (slug, locale) do update set prompt = excluded.prompt, context = excluded.context, options = excluded.options, takeaway = excluded.takeaway, lesson_slug = excluded.lesson_slug, sort_order = excluded.sort_order;

-- Challenges
